B.a2b=new A.e5(B.Qd,"S\u1eeda nh\xe0, t\xecm th\u1ee3 uy t\xedn g\u1ea7n b\u1ea1n","Th\u1ee3 v\xe0 th\u1ea7u kh\u1eafp An Giang: s\u01a1n, \u0111i\u1ec7n n\u01b0\u1edbc, ch\u1ed1ng th\u1ea5m, x\xe2y s\u1eeda... Xem h\u1ed3 s\u01a1, c\xf4ng tr\xecnh th\u1eadt v\xe0 \u0111\xe1nh gi\xe1 tr\u01b0\u1edbc khi thu\xea.")
B.uk=new A.an(58671,"MaterialIcons",!1)
B.a2c=new A.e5(B.uk,"\u0110\u0103ng vi\u1ec7c mi\u1ec5n ph\xed, nh\u1eadn b\xe1o gi\xe1","Ch\u1ee7 nh\xe0 m\xf4 t\u1ea3 vi\u1ec7c c\u1ea7n l\xe0m, th\u1ee3 g\u1ea7n b\u1ea1n g\u1eedi b\xe1o gi\xe1. So s\xe1nh r\u1ed3i chat tr\u1ef1c ti\u1ebfp, kh\xf4ng l\u1ed9 s\u1ed1 \u0111i\u1ec7n tho\u1ea1i.")
B.a2d=new A.e5(B.uo,"\u0110\xe1nh gi\xe1 th\u1eadt, an t\xe2m h\u01a1n",'Ch\u1ec9 kh\xe1ch \u0111\xe3 thu\xea qua app v\xe0 b\u1ea5m "\u0110\xe3 ho\xe0n th\xe0nh" m\u1edbi \u0111\u01b0\u1ee3c \u0111\xe1nh gi\xe1. Th\u1ea5y d\u1ea5u hi\u1ec7u l\u1eeba \u0111\u1ea3o, b\u1ea5m B\xe1o c\xe1o.')
